@Component
class PaymentListener {

    static final long RETRY_DELAY_MS = 2_000;

    static final int POOL_THREADS = 4;

    private final PaymentService service;

    private final KafkaTemplate<String, String> kafka;

    private final JsonMapper json;

    private final boolean retryTopic;

    private final ExecutorService pool;

    PaymentListener(PaymentService service, KafkaTemplate<String, String> kafka, JsonMapper json, @Value("${payments.retries:retry-topic}") String retries, @Value("${payments.processing:thread-pool}") String processing) {
        this.service = service;
        this.kafka = kafka;
        this.json = json;
        this.retryTopic = retries.equals("retry-topic");
        this.pool = processing.equals("thread-pool") ? Executors.newFixedThreadPool(POOL_THREADS, Thread.ofPlatform().name("payment-pool-", 1).factory()) : null;
    }

    @KafkaListener(topics = TopicConfig.PAYMENTS_REQUESTED, groupId = "payment-worker")
    void onMessage(String payload, Acknowledgment ack) throws Exception {
        var event = json.readValue(payload, PaymentEvent.class);
        if (pool != null) {
            pool.submit(() -> service.process(event));
            ack.acknowledge();
            return;
        }
        try {
            service.process(event);
        } catch (RuntimeException e) {
            if (!retryTopic)
                throw e;
            kafka.send(TopicConfig.PAYMENTS_RETRY, event.accountId(), payload).get();
        }
        ack.acknowledge();
    }

    @KafkaListener(topics = TopicConfig.PAYMENTS_RETRY, groupId = "payment-retry")
    void onRetry(String payload, Acknowledgment ack) throws Exception {
        Thread.sleep(RETRY_DELAY_MS);
        service.process(json.readValue(payload, PaymentEvent.class));
        ack.acknowledge();
    }

    @PreDestroy
    void stop() {
        if (pool != null)
            pool.shutdown();
    }
}

@Service
class PaymentService {

    enum Dedupe {

        NONE,
        CHECK_THEN_INSERT,
        CLAIM_FIRST
    }

    private final JdbcClient db;

    private final Dedupe dedupe;

    private final boolean byEventId;

    private final ProviderClient provider;

    private final MerchantBalance merchant;

    private final CompletedEvents completed;

    PaymentService(JdbcClient db, @Value("${payments.dedupe:none}") String dedupe, @Value("${payments.dedupe-key:event-id}") String key, ProviderClient provider, MerchantBalance merchant, CompletedEvents completed) {
        this.db = db;
        this.dedupe = Dedupe.valueOf(dedupe.toUpperCase(Locale.ROOT).replace('-', '_'));
        this.byEventId = key.equals("event-id");
        this.provider = provider;
        this.merchant = merchant;
        this.completed = completed;
    }

    @Transactional
    public void process(PaymentEvent p) {
        switch(dedupe) {
            case NONE ->
                apply(p);
            case CHECK_THEN_INSERT ->
                {
                    if (alreadyProcessed(p))
                        return;
                    apply(p);
                    markProcessed(p);
                }
            case CLAIM_FIRST ->
                {
                    if (markProcessed(p) == 0)
                        return;
                    apply(p);
                }
        }
    }

    void apply(PaymentEvent p) {
        provider.charge(p);
        db.sql("update accounts set balance_minor = balance_minor - ? where account_id = ?").params(p.amountMinor(), p.accountId()).update();
        merchant.credit(p.amountMinor());
        db.sql("insert into payments(payment_id, account_id, amount_minor) values (?, ?, ?)").params(p.paymentId(), p.accountId(), p.amountMinor()).update();
        completed.paymentApplied(p);
    }

    private boolean alreadyProcessed(PaymentEvent p) {
        return db.sql("select exists(select 1 from processed_events where payment_id = ?)").param(key(p)).query(Boolean.class).single();
    }

    private int markProcessed(PaymentEvent p) {
        return db.sql("insert into processed_events(payment_id) values (?) on conflict do nothing").param(key(p)).update();
    }

    private String key(PaymentEvent p) {
        return byEventId ? p.eventId() : p.paymentId();
    }
}

@Component
class CompletedEvents {

    private record OutboxRow(long id, String key, String payload) {
    }

    private final KafkaTemplate<String, String> kafka;

    private final JdbcClient db;

    private final JsonMapper json;

    private final ApplicationEventPublisher events;

    private final boolean outbox;

    CompletedEvents(KafkaTemplate<String, String> kafka, JdbcClient db, JsonMapper json, ApplicationEventPublisher events, @Value("${payments.completed-events:after-commit}") String mode) {
        this.kafka = kafka;
        this.db = db;
        this.json = json;
        this.events = events;
        this.outbox = mode.equals("outbox");
    }

    void paymentApplied(PaymentEvent p) {
        var event = new PaymentCompleted(p.paymentId(), p.accountId(), p.amountMinor());
        if (outbox) {
            db.sql("insert into outbox(event_key, payload) values (?, ?)").params(p.accountId(), json.writeValueAsString(event)).update();
        } else {
            events.publishEvent(event);
        }
    }

    @TransactionalEventListener
    void onCommitted(PaymentCompleted event) {
        publish(event.accountId(), json.writeValueAsString(event));
    }

    @Scheduled(fixedDelay = 200)
    @Transactional
    public void publishOutbox() {
        if (!outbox)
            return;
        var rows = db.sql("select id, event_key, payload from outbox order by id limit 100 for update skip locked").query((rs, n) -> new OutboxRow(rs.getLong(1), rs.getString(2), rs.getString(3))).list();
        for (var row : rows) {
            publish(row.key(), row.payload());
            db.sql("delete from outbox where id = ?").param(row.id()).update();
        }
    }

    void publish(String key, String payload) {
        try {
            kafka.send(TopicConfig.PAYMENTS_COMPLETED, key, payload).get();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("interrupted while publishing a completed payment", e);
        } catch (ExecutionException e) {
            throw new IllegalStateException("could not publish a completed payment", e.getCause());
        }
    }
}

@RestController
class PaymentController {

    private final KafkaTemplate<String, String> kafka;

    private final JsonMapper json;

    private final String topic;

    PaymentController(KafkaTemplate<String, String> kafka, JsonMapper json, @Value("${payments.inbound-topic:payments.requested}") String topic) {
        this.kafka = kafka;
        this.json = json;
        this.topic = topic;
    }

    @PostMapping("/payments")
    ResponseEntity<Void> pay(@RequestBody PaymentRequested req) throws Exception {
        var event = new PaymentEvent(UUID.randomUUID().toString(), req.paymentId(), req.accountId(), req.amountMinor());
        kafka.send(topic, req.accountId(), json.writeValueAsString(event)).get();
        return ResponseEntity.accepted().build();
    }
}
